import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import './AdminDashboard.css';
import { apiClient } from '../utils/authService';

const AdminDashboard = ({ user, onLogout }) => {
  const [dateFilter, setDateFilter] = useState('today');
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [stats, setStats] = useState(null);
  const [employees, setEmployees] = useState([]);

  useEffect(() => {
    fetchDashboardStats();
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    try {
      const { data } = await apiClient.get('/employees');
      setEmployees(data?.employees || []);
    } catch (error) {
      console.error('Error fetching employees:', error);
    }
  };

  const fetchDashboardStats = async () => {
    try {
      const { data } = await apiClient.get('/dashboard/stats');
      setStats(data?.stats || null);
    } catch (error) {
      console.error('Failed to fetch dashboard stats:', error);
    }
  };

  const formattedDate = selectedDate.toLocaleDateString('en-US', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });

  const shiftDate = (days) => {
    setSelectedDate((prev) => {
      const next = new Date(prev);
      next.setDate(prev.getDate() + days);
      return next;
    });
  };

  const setFilterAndDate = (filter) => {
    setDateFilter(filter);
    const today = new Date();

    if (filter === 'today') {
      setSelectedDate(today);
    } else if (filter === 'week') {
      const lastWeek = new Date();
      lastWeek.setDate(today.getDate() - 7);
      setSelectedDate(lastWeek);
    } else if (filter === 'month') {
      const lastMonth = new Date();
      lastMonth.setMonth(today.getMonth() - 1);
      setSelectedDate(lastMonth);
    }
  };

  return (
    <div className="admin-container">
      <Navbar user={user} onLogout={onLogout} />
      
      <div className="container">
        <div className="welcome-section">
          <h1>Welcome, {user?.employeeName || 'Admin'}</h1>
          
          <div className="filter-section">
            <span>Filter by Date:</span>
            <div className="filter-buttons">
              <button 
                className={dateFilter === 'today' ? 'active' : ''} 
                onClick={() => setFilterAndDate('today')}
              >
                Today
              </button>
              <button 
                className={dateFilter === 'week' ? 'active' : ''} 
                onClick={() => setFilterAndDate('week')}
              >
                Last Week
              </button>
              <button 
                className={dateFilter === 'month' ? 'active' : ''} 
                onClick={() => setFilterAndDate('month')}
              >
                Last Month
              </button>
            </div>
            <div className="date-controls">
              <button className="nav-btn" aria-label="Previous date" onClick={() => shiftDate(-1)}>‹</button>
              <div className="date-display">
                <span className="calendar-icon">📅</span>
                <span>{formattedDate}</span>
              </div>
              <button className="nav-btn" aria-label="Next date" onClick={() => shiftDate(1)}>›</button>
            </div>
          </div>
        </div>

        <div className="dashboard-grid">
          <div className="placeholder-message">
            {stats ? (
              <div style={{ textAlign: 'left', padding: '20px' }}>
                <h3>📊 System Statistics</h3>
                <p>Total Employees: <strong>{employees.length || stats.total_employees || 0}</strong></p>
                <p>Present Today: <strong>{stats.today_present || 0}</strong></p>
                <p>Pending Salaries: <strong>{stats.pending_salaries || 0}</strong> (₱{(stats.pending_amount || 0).toLocaleString()})</p>
                <p>Week Attendance: <strong>{stats.week_attendance || 0}</strong> check-ins</p>
              </div>
            ) : (
              <>
                <p>📊 Loading dashboard statistics...</p>
                <p style={{ fontSize: '12px', color: '#bbb', marginTop: '8px' }}>Fetching from database</p>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
